bool isOdd(int x)  { return (x & 1) != 0; }
bool isEven(int x) { return (x & 1) == 0; }
// TRUTH TABLE: any binary number ends in 0 (even) or 1 (odd). ANDing with 1
// keeps only that last bit and discards everything else.
// TWO'S COMPLEMENT: -7 is ...11111001, so -7 & 1 == 1 -- still correctly odd.
// This is why x & 1 beats x % 2 for parity: in C++, -7 % 2 is -1, not 1.

string toBinary32(unsigned int n) {
    string out;
    out.reserve(32);
    for (int i = 31; i >= 0; --i)          // MSB first
        out += char('0' + ((n >> i) & 1));
    return out;
}

// Minimal-width version: skip the leading zeros, but keep "0" for zero itself.
string toBinaryMin(unsigned int n) {
    if (n == 0) return "0";
    int top = 31;
    while (((n >> top) & 1) == 0) --top;   // find the highest set bit
    string out;
    for (int i = top; i >= 0; --i) out += char('0' + ((n >> i) & 1));
    return out;
}

