def to_binary_min(n: int) -> str:
    """Minimal width: skip leading zeros, but keep '0' for zero itself."""
    if n == 0:
        return "0"
    n &= 0xFFFFFFFF
    top = 31
    while not (n >> top) & 1:
        top -= 1                          # find the highest set bit
    return "".join(str((n >> i) & 1) for i in range(top, -1, -1))

