// The mask 1 << k isolates exactly bit k. Every operation is that mask
// combined with the right boolean operator.
bool getBit(int n, int k)    { return ((n >> k) & 1) != 0; }
int  setBit(int n, int k)    { return n |  (1 << k); }   // OR forces it to 1
int  clearBit(int n, int k)  { return n & ~(1 << k); }   // AND with the inverse forces 0
int  toggleBit(int n, int k) { return n ^  (1 << k); }   // XOR flips it

// Bonus: update bit k to a given value without branching.
int updateBit(int n, int k, bool value) {
    return (n & ~(1 << k)) | ((value ? 1 : 0) << k);      // clear, then OR in
}

