bool isPowerOfTwoNaive(int n) {
    if (n <= 0) return false;      // THE TRAP: 0 would loop-exit at 0, not 1;
                                   // negatives are never powers of two.
    while (n % 2 == 0) n /= 2;     // strip factors of 2
    return n == 1;                 // anything left over means an odd factor existed
}

