// TRACE with a=5 (0101), b=9 (1001):
//   a ^= b  ->  a = 0101 ^ 1001 = 1100 (12)
//   b ^= a  ->  b = 1001 ^ 1100 = 0101 (5)   <- b now holds the original a
//   a ^= b  ->  a = 1100 ^ 0101 = 1001 (9)   <- a now holds the original b
void xorSwap(int& a, int& b) {
    if (&a == &b) return;    // CAVEAT: aliasing self-zeros both to 0. Guard it.
    a ^= b;
    b ^= a;
    a ^= b;
}

// STYLE A -- shift the NUMBER right, then read bit 0.
bool isKthBitSetA(int n, int k) { return ((n >> k) & 1) != 0; }

// STYLE B -- shift the MASK left, then test with AND.
bool isKthBitSetB(int n, int k) { return (n & (1 << k)) != 0; }

// Equivalent for k in range. Style A is safer when n may be negative and you
// use an unsigned type; style B avoids shifting the value itself, which some
// codebases prefer for readability. Both are UB if k >= bit width.

int mulPow2(int n, int k) { return n << k; }   // n * 2^k
int divPow2(int n, int k) { return n >> k; }   // FLOOR division by 2^k

// NEGATIVE CAVEAT: right shift FLOORS toward negative infinity, but integer
// division TRUNCATES toward zero. They disagree on negatives:
//   -7 >> 1  == -4    (floor of -3.5)
//   -7 / 2   == -3    (truncation of -3.5)
