// Returns the 0-indexed position of the most significant set bit,
// or -1 for n == 0 (which has no set bits at all).
int highestSetBit(unsigned int n) {
    if (n == 0) return -1;
    int pos = -1;
    while (n) { ++pos; n >>= 1; }   // each shift discards one bit
    return pos;                      // pos == floor(log2(original n))
}

// Hardware version: __builtin_clz counts LEADING zeros, so 31 minus that is
// the MSB index. Undefined for n == 0, hence the guard.
int highestSetBitFast(unsigned int n) {
    return n == 0 ? -1 : 31 - __builtin_clz(n);
}

