    return pos                     # equals floor(log2(original n))


def highest_set_bit_fast(n: int) -> int:
    """Python's int.bit_length() is the hardware-intrinsic equivalent."""
    return -1 if n == 0 else (n & 0xFFFFFFFF).bit_length() - 1

