int binaryGap(unsigned int n) {
    int best = 0, lastOne = -1;
    for (int i = 0; i < 32; ++i) {
        if (((n >> i) & 1) == 0) continue;      // zeros are skipped, including LEADING ones
        if (lastOne >= 0) best = max(best, i - lastOne);   // distance between adjacent 1s
        lastOne = i;
    }
    return best;                                 // 0 when there are fewer than two 1s
}

