def binary_gap(n: int) -> int:
    best, last_one = 0, -1
    n &= 0xFFFFFFFF
    for i in range(32):
        if not (n >> i) & 1:
            continue                       # zeros skipped, including LEADING ones
        if last_one >= 0:
            best = max(best, i - last_one)  # distance between adjacent 1s
        last_one = i
    return best                             # 0 when there are fewer than two 1s
